import socket, struct, random
def query(server, name):
    tid=random.randint(0,65535)
    hdr=struct.pack(">HHHHHH", tid,0x0100,1,0,0,0)
    q=b"".join(bytes([len(l)])+l.encode() for l in name.split("."))+b"\x00"+struct.pack(">HH",1,1)
    s=socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(2)
    try:
        s.sendto(hdr+q,(server,53))
        data,_=s.recvfrom(1024)
        ancount=struct.unpack(">H",data[6:8])[0]
        return f"{name}@{server}: rcode={data[3]&0xF} answers={ancount}"
    except Exception as e:
        return f"{name}@{server}: {e}"
for srv in ["127.0.0.11","192.168.65.7"]:
