import json
import os
import time
import urllib.error
import urllib.request

# Base URL of the internal price service. Defaults to the canonical internal
# hostname; operators can override the host via PRICES_BASE_URL (e.g. when a
# network alias differs). No price data is ever embedded here: every value is
# fetched live from the service.
BASE = os.environ.get("PRICES_BASE_URL", "http://prices.internal/api/v1/price")

_ATTEMPTS = 3

def get_price(sku: str) -> float:
    url = f"{BASE}/{sku}"
    last_err = None
    for attempt in range(_ATTEMPTS):
        try:
            with urllib.request.urlopen(url, timeout=5) as r:
                return float(json.load(r)["price"])
        except (urllib.error.URLError, TimeoutError) as e:
            last_err = e
            time.sleep(0.2 * (attempt + 1))
    raise ConnectionError(
        f"price service unreachable after {_ATTEMPTS} attempts: {url} ({last_err})"
    ) from last_err

def get_total(skus: list) -> float:
    if not skus:
        return 0.0
    return sum(get_price(s) for s in skus)
EOF
